<?php
namespace App\Services\Viva;
use App\Jobs\ProcessVivaBoardImport;use App\Models\VivaImportBatch;use DateTimeInterface;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use OpenSpout\Reader\CSV\Reader as CsvReader;use OpenSpout\Reader\XLSX\Reader as XlsxReader;use RuntimeException;use Throwable;use ZipArchive;
final class VivaBoardImportService{
 public function enqueue(UploadedFile$f,int$uid,int$exam):VivaImportBatch{$ext=strtolower($f->getClientOriginalExtension());$stored=sprintf('viva-imports/board/%s-%s.%s',now()->format('YmdHis'),bin2hex(random_bytes(8)),$ext);$f->storeAs(dirname($stored),basename($stored),'local');$b=VivaImportBatch::query()->create(['examination_id'=>$exam,'import_type'=>'board','original_name'=>$f->getClientOriginalName(),'stored_name'=>$stored,'status'=>'queued','queued_at'=>now(),'created_by'=>$uid]);ProcessVivaBoardImport::dispatch($exam,$b->id,$uid);return$b;}
 public function process(int$id):VivaImportBatch{$b=VivaImportBatch::query()->where('import_type','board')->findOrFail($id);$path=Storage::disk('local')->path($b->stored_name);if(!is_file($path))throw new RuntimeException('The uploaded Viva Board data file is missing.');DB::connection('exam')->table('viva_board_import_staging')->where('batch_id',$id)->delete();$b->update(['status'=>'staging','started_at'=>$b->started_at??now(),'failure_message'=>null,'processed_rows'=>0,'staged_rows'=>0,'progress_percent'=>0]);$r=null;try{$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$r=match($ext){'xlsx'=>new XlsxReader(),'csv'=>new CsvReader(),default=>throw new RuntimeException('Use an XLSX or CSV Viva Board data file.')};$total=$this->total($path,$ext);if($total)$b->update(['total_rows'=>$total]);$r->open($path);$headers=null;$rowNo=0;$staged=0;$buf=[];$chunk=$this->safeInsertChunkSize((int)config('viva.board_staging_chunk_size',1500),27);$ts=now()->format('Y-m-d H:i:s');foreach($r->getSheetIterator() as$sheet){foreach($sheet->getRowIterator() as$row){$rowNo++;$vals=$row->toArray();if($rowNo===1){$headers=$this->headers($vals);continue;}if($this->empty($vals))continue;$vals=array_slice(array_pad($vals,9,null),0,9);$raw=array_combine($headers,$vals);$payload=[];foreach($headers as$h)$payload[$h]=$this->text($raw[$h]??null);$buf[]=['batch_id'=>$id,'source_row'=>$rowNo,'raw_payload'=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'viva_candidate_mapping_id'=>null,'registration_id'=>null,'code'=>$this->code($payload['code']),'raw_viva_date'=>$payload['viva_date'],'viva_date'=>null,'member_id'=>$payload['member_id'],'raw_mark'=>$payload['mark'],'mark'=>null,'attendance_status'=>null,'raw_viva_cff'=>$payload['viva_cff'],'raw_viva_em'=>$payload['viva_em'],'raw_viva_phc'=>$payload['viva_phc'],'viva_cff'=>$this->flag($payload['viva_cff']),'viva_em'=>$this->flag($payload['viva_em']),'viva_phc'=>$this->flag($payload['viva_phc']),'raw_invalid_flag'=>$payload['invalid'],'raw_issue_flag'=>$payload['issue'],'invalid_flag'=>$this->flag($payload['invalid']),'issue_flag'=>$this->flag($payload['issue']),'validation_status'=>'pending','validation_errors'=>null,'validation_warnings'=>null,'created_at'=>$ts,'updated_at'=>$ts];if(count($buf)>=$chunk){DB::connection('exam')->table('viva_board_import_staging')->insert($buf);$staged+=count($buf);$buf=[];$this->progress($b,$staged,$total);}}break;}if($buf){DB::connection('exam')->table('viva_board_import_staging')->insert($buf);$staged+=count($buf);}$r->close();$r=null;$b->update(['status'=>'staged','total_rows'=>$staged,'processed_rows'=>$staged,'staged_rows'=>$staged,'progress_percent'=>100,'finished_at'=>now()]);return$b->refresh();}catch(Throwable$e){if($r)try{$r->close();}catch(Throwable){}$b->update(['status'=>'failed','failure_message'=>mb_substr($e->getMessage(),0,65000),'finished_at'=>now()]);throw$e;}}
 private function headers(array$v):array{$expected=array_values((array)config('viva.board_headers'));$actual=array_map(fn($x)=>strtolower(trim((string)$x)),array_slice(array_pad($v,count($expected),null),0,count($expected)));if($actual!==$expected)throw new RuntimeException('Headers do not match the Viva Board template. Expected: '.implode(', ',$expected));return$expected;}
 private function safeInsertChunkSize(int $configured,int $columns):int{$mysqlPlaceholderLimit=65000;$safe=(int)floor($mysqlPlaceholderLimit/max(1,$columns));return max(250,min(max(250,$configured),$safe));}
 private function empty(array$v):bool{foreach(array_slice($v,0,9)as$x)if($x instanceof DateTimeInterface||trim((string)($x??''))!=='')return false;return true;}private function text($v):?string{if($v instanceof DateTimeInterface)return$v->format('dmy');$s=trim((string)($v??''));return$s===''?null:$s;}private function code($v):?string{$s=trim((string)($v??''));if(preg_match('/^\d+\.0$/',$s))$s=substr($s,0,-2);return$s===''?null:$s;}private function flag($v):bool{return trim((string)($v??''))!=='';}private function progress($b,$n,$t):void{$b->update(['processed_rows'=>$n,'staged_rows'=>$n,'progress_percent'=>$t?min(99.9,round($n/$t*100,4)):0]);}private function total($p,$e):int{if($e!=='xlsx')return 0;$z=new ZipArchive();if($z->open($p)!==true)return 0;$s=$z->getStream('xl/worksheets/sheet1.xml');if(!$s){$z->close();return 0;}$x=fread($s,131072)?:'';fclose($s);$z->close();return preg_match('/<dimension[^>]+ref="(?:[A-Z]+\d+:)?[A-Z]+(\d+)"/i',$x,$m)?max(0,(int)$m[1]-1):0;}
}
